steps.run:
cd ${{ env.APP_NAME }}
npm ci
npm run build --if-present

set -euo pipefail
jmap() {
  jq -nc --argjson call "$1" '{using: ["urn:ietf:params:jmap:core", "urn:stalwart:jmap"], methodCalls: [$call]}' \
    | curl -sSf -u "admin:$STALWART_PWD" -H 'Content-Type: application/json' -d @- http://stalwart:8080/jmap/ \
    | jq -e '.methodResponses[0] | if .[0] == "error" or ((.[1].notCreated // .[1].notUpdated // {}) | length > 0) then error(tojson) else .[1] end'
}
wait_for() {
  timeout 120 sh -c "until curl -sf '$1' > /dev/null; do sleep 2; done"
}

# A fresh server starts in bootstrap mode and only accepts the Bootstrap object
wait_for http://stalwart:8080/healthz/live
jmap '["x:Bootstrap/set", {"update": {"singleton": {
  "defaultHostname": "mail.example.com",
  "defaultDomain": "example.com",
  "requestTlsCertificate": false,
  "generateDkimKeys": false,
  "tracer": {"@type": "Stdout"}
}}}, "0"]'

# The configuration written by the bootstrap is only loaded on restart
docker restart "$STALWART_CONTAINER"
wait_for http://stalwart:8080/healthz/ready

domain_id=$(jmap '["x:Domain/query", {"filter": {"name": "example.com"}}, "0"]' | jq -er '.ids[0]')
jmap "$(jq -nc --arg domain "$domain_id" --arg pwd "$STALWART_USER_PWD" '["x:Account/set", {"create": {"u1": {
  "@type": "User",
  "name": "user",
  "domainId": $domain,
  "credentials": {"0": {"@type": "Password", "secret": $pwd}}
}}}, "0"]')"

EXPORTED_ZIP=$(find $EXPORT_DIRECTORY -name "$TEST_USER*.zip" | tail -1)
unzip -l "$EXPORTED_ZIP" | grep -q 'mail/accounts/.*\.json' \
  || { echo "::error::no account file in the export"; unzip -l "$EXPORTED_ZIP"; exit 1; }

php -f nextcloud/occ mail:account:export $TEST_USER | tee /tmp/imported-accounts.txt
grep -q "E-Mail: $TEST_EMAIL" /tmp/imported-accounts.txt \
  || { echo "::error::imported user has no mail account"; exit 1; }
grep -q "IMAP user: $TEST_EMAIL" /tmp/imported-accounts.txt \
  || { echo "::error::imported account lost its IMAP username"; exit 1; }
